#include <cstdio>
#include <deque>
#include <cstring>
using namespace std;

typedef struct {
    int x, y, cost, ch;
} mouse;

int dx[] = {0, 1, 0, -1}, dy[] = {1, 0, -1, 0};
int maxch[1000][1000];

int main() {
    int h, w, n;
    scanf("%d %d %d", &h, &w, &n);
    char ku[100][100];
    for (int i = 0; i < h; i++) scanf("%s", ku[i]);

    int sx, sy;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (ku[i][j] == 'S') sx = i, sy = j;
        }
    }

    deque<mouse> Q; // Changed from queue to deque
    memset(maxch, -1, sizeof(maxch));
    Q.push_back((mouse){sx, sy, 0, 0});
    maxch[sx][sy] = 0;

    int ans = 0;
    while (!Q.empty()) {
        mouse t = Q.front(); Q.pop_front(); // Changed from Q.pop() to Q.pop_front()
        int cx = t.x, cy = t.y, cost = t.cost, ch = t.ch;

        if (ch == n) {
            ans = cost;
            break;
        }

        for (int i = 0; i < 4; i++) {
            int nx = cx + dx[i], ny = cy + dy[i];
            if (nx < 0 || nx >= h || ny < 0 || ny >= w) continue;
            if (ku[nx][ny] == 'X') continue;
            int nch = ch;
            if (ku[nx][ny] >= '1' && ku[nx][ny] <= '9') {
                int num = ku[nx][ny] - '0';
                if (num == t.ch + 1) nch = ch + 1;
            }
            if (maxch[nx][ny] >= nch) continue;

            maxch[nx][ny] = nch;
            Q.push_back((mouse){nx, ny, cost + 1, nch}); // Changed from Q.push() to Q.push_back()
        }
    }
    printf("%d\n", ans);
}

